settings.custom_css:
selector {
  background: linear-gradient(84deg, #A55BDA 0%, #A55BDA 72%, #8535BB 100%) !important;
  color: #fff !important;
  border-radius: 16px !important;
  position: relative !important;
  overflow: hidden !important;
  z-index: 1 !important;
  transition: transform 0.3s ease, box-shadow 0.3s ease !important;
  animation: pulseShadow 2.2s ease-in-out infinite !important;
  box-shadow:
    0 0 0 rgba(165, 91, 218, 0),
    0 10px 24px rgba(133, 53, 187, 0.35) !important;
}

/* linha de luz passando */
selector::after {
  content: "";
  position: absolute;
  top: 0;
  left: -100%;
  width: 60%;
  height: 100%;
  background: linear-gradient(
    120deg,
    transparent,
    rgba(255,255,255,0.5),
    transparent
  );
  transform: skewX(-20deg);
  transition: left 0.7s ease !important;
  z-index: 2;
  pointer-events: none;
}

/* glow suave interno no topo */
selector::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    rgba(255,255,255,0.22) 0%,
    rgba(255,255,255,0.08) 22%,
    rgba(255,255,255,0) 55%
  );
  pointer-events: none;
  z-index: 1;
}

/* hover */
selector:hover {
  transform: translateY(-2px) scale(1.03) !important;
  box-shadow:
    0 0 18px rgba(165, 91, 218, 0.25),
    0 14px 34px rgba(133, 53, 187, 0.45),
    0 0 42px rgba(165, 91, 218, 0.25) !important;
}

/* mantém a luz no hover */
selector:hover::after {
  left: 125%;
}

/* animação de pulsação */
@keyframes pulseShadow {
  0% {
    box-shadow:
      0 0 0 rgba(165, 91, 218, 0),
      0 10px 24px rgba(133, 53, 187, 0.30);
  }
  50% {
    box-shadow:
      0 0 26px rgba(165, 91, 218, 0.22),
      0 12px 30px rgba(133, 53, 187, 0.45);
  }
  100% {
    box-shadow:
      0 0 0 rgba(165, 91, 218, 0),
      0 10px 24px rgba(133, 53, 187, 0.30);
  }
}

